// Auth fix support: the standard requireAuth middleware and a line-preserving import insertion.
import path from 'node:path';
import { walk } from '../lib/ast.js';

const MW_FILE = /(?:^|\/)requireAuth\.(?:c|m)?js$/;

const CJS_HEAD = { jwt: "const jwt = require('jsonwebtoken');\n", token: "const crypto = require('node:crypto');\n" };
const ESM_HEAD = { jwt: "import jwt from 'jsonwebtoken';\n", token: "import crypto from 'node:crypto';\n" };

const BODY = {
  jwt: `
// Generated by SlopStop. Expects "Authorization: Bearer <jwt>" signed with JWT_SECRET.
function requireAuth(req, res, next) {
  const header = req.headers.authorization || '';
  const token = header.startsWith('Bearer ') ? header.slice(7) : null;
  if (!token || !process.env.JWT_SECRET) return res.status(401).json({ error: 'Unauthorized' });
  try {
    req.user = jwt.verify(token, process.env.JWT_SECRET);
    return next();
  } catch {
    return res.status(401).json({ error: 'Unauthorized' });
  }
}
`,
  token: `
// Generated by SlopStop. Expects "Authorization: Bearer <API_TOKEN>".
function requireAuth(req, res, next) {
  const header = req.headers.authorization || '';
  const given = Buffer.from(header.startsWith('Bearer ') ? header.slice(7) : '');
  const expected = Buffer.from(process.env.API_TOKEN || '');
  if (!expected.length || given.length !== expected.length || !crypto.timingSafeEqual(given, expected)) {
    return res.status(401).json({ error: 'Unauthorized' });
  }
  return next();
}
`,
};

/** Source of middleware/requireAuth.js. kind: 'jwt' | 'token'. */
export function middlewareSource(kind, esm, envName = middlewareEnv(kind)) {
  const body = BODY[kind].replaceAll(middlewareEnv(kind), envName);
  return (esm ? ESM_HEAD : CJS_HEAD)[kind] + body + (esm ? '\nexport default requireAuth;\n' : '\nmodule.exports = requireAuth;\n');
}

export const middlewareEnv = (kind) => (kind === 'jwt' ? 'JWT_SECRET' : 'API_TOKEN');

/** Where the middleware lives: an existing requireAuth file, else next to other middleware, else src/ or root. */
export function middlewarePath(paths) {
  const existing = paths.find((p) => MW_FILE.test(p));
  if (existing) return { path: existing, exists: true };
  const mwDir = paths.map((p) => p.match(/^(.*?\/?middlewares?)\//)?.[1]).find(Boolean);
  if (mwDir) return { path: `${mwDir}/requireAuth.js`, exists: false };
  const underSrc = paths.filter((p) => p.startsWith('src/')).length > paths.length / 2;
  return { path: underSrc ? 'src/middleware/requireAuth.js' : 'middleware/requireAuth.js', exists: false };
}

export function importSpecifier(fromFile, mwPath) {
  let rel = path.posix.relative(path.posix.dirname(fromFile), mwPath);
  if (!rel.startsWith('.')) rel = `./${rel}`;
  return rel;
}

/** Is `requireAuth` already declared/imported at any level of this file? */
export function hasRequireAuthBinding(ast) {
  let found = false;
  walk(ast, (n) => {
    if (found) return;
    if ((n.type === 'ImportDefaultSpecifier' || n.type === 'ImportSpecifier') && n.local.name === 'requireAuth') found = true;
    if (n.type === 'VariableDeclarator') {
      walk(n.id, (id) => {
        if (id.type === 'Identifier' && id.name === 'requireAuth') found = true;
      });
    }
    if (n.type === 'FunctionDeclaration' && n.id?.name === 'requireAuth') found = true;
  });
  return found;
}

const isRequireDecl = (n) =>
  n.type === 'VariableDeclaration' &&
  n.declarations.some((d) => {
    let init = d.init;
    while (init?.type === 'MemberExpression') init = init.object;
    if (init?.type === 'CallExpression' && init.callee.type === 'MemberExpression') init = init.callee.object;
    return init?.type === 'CallExpression' && init.callee.type === 'Identifier' && init.callee.name === 'require';
  });

/**
 * Edit that adds the import WITHOUT adding a line, so finding ids (rule:file:line) stay stable:
 * appended after the last top-level import/require, else before the first statement.
 */
export function importEdit(ast, esm, spec) {
  const stmt = esm ? `import requireAuth from '${spec}';` : `const requireAuth = require('${spec}');`;
  const body = ast.body;
  const last = [...body].reverse().find((n) => n.type === 'ImportDeclaration' || isRequireDecl(n));
  if (last) return { start: last.end, end: last.end, text: ` ${stmt}` };
  const first = body.find((n) => !n.directive) ?? null;
  if (first) return { start: first.start, end: first.start, text: `${stmt} ` };
  const end = body.length ? body[body.length - 1].end : 0;
  return { start: end, end, text: ` ${stmt}` };
}
